fn v50_fold_dive_episode(&mut self, _version: usize, _tps: usize, aborted: bool, end_reason: u8)   // rs:125
// _version/_tps 는 IR 시그니처에서 아예 사라짐(미사용). 실제 IR 인자는 (self, i1 aborted, i8 end_reason) 3개.

// ─── (A) '접촉 없이 끝난 다이브' 포기 시각 집계 — rs:131~141 ────────────────
// as_ref() 가 인라인돼 판별자 비교로 접혔다: self+0x570 의 i64 != -1 == is_some.
if self.v50_dive_ep_live.is_some() && live.in_range_ticks == 0 {   // rs:131, self+0x598 == 0
    let no_contact = (live.team_holder_ticks == 0);                // rs:138, self+0x5a8
    // IR: %24 = (end_reason == 7) || (team_holder_ticks != 0); br %24 -> skip
    if no_contact && end_reason != 7 {                             // rs:139
        self.last_dive_abandon_tick =                              // self+0x1480
            max(self.last_dive_abandon_tick, live.last_tick);      // rs:140, Ord::max -> llvm.umax.i64, self+0x588
    }
}
// ⚠ 위 블록은 순수 집계다. 아래 (B)(C) 로 가는 흐름은 이 분기와 무관하게 항상 합류한다.

// ─── (B) end_plan 분류 — live 유무와 무관하게 **항상** 실행 — rs:144~154 ─────
let n: String = self.plan.get_name();   // BigPlan @ self+0x5e8 (384B), 24B String 을 sret 로 받음
let end_plan: u8 =
         if n.starts_with("PassiveLine")   { 1 }   // rs:146
    else if n.starts_with("PassiveJungle") { 2 }   // rs:147
    else if n.starts_with("LineGank")      { 3 }   // rs:148
    else if n.contains("Epic")             { 4 }   // rs:149  (Pattern::is_contained_in)
    else if n.contains("Serpen")           { 5 }   // rs:150  (Pattern::is_contained_in)
    else if n.starts_with("ActiveRecall")
         || n.starts_with("Recall")        { 6 }   // rs:151  (두 검사 모두 !dbg line 151 -> 같은 줄의 || )
    else if n.starts_with("Battle")        { 7 }   // rs:152
    else if n.contains("Nexus")            { 8 }   // rs:153  (Pattern::is_contained_in)
    else                                   { 9 };  // rs:153  (select i1 %70, i8 8, i8 9)
drop(n);   // Vec<u8>::drop + RawVec::drop. 언와인딩 경로엔 String drop_glue cleanuppad.

// ─── (C) 에피소드 확정 후 통계 Vec 에 push — rs:156~ ─────────────────────────
let done = self.v50_dive_ep_live.take();   // rs:156. mem::replace 인라인 -> self+0x570 에 -1 저장
if let Some(done) = done {                 // 필드값을 모두 미리 로드한 뒤 (old != -1) 로 판정
    self.v50_dive_episodes.push(V50DiveEpisode {   // rs:157, Vec @ self+0x888/0x890/0x898, 원소 104B
        // ── V50DiveEpLive -> V50DiveEpisode 필드 대응 (전부 단순 복사) ──
        max_catch_break   : done.max_catch_break,     // +0x00 <- live+0x58
        uncatch_total     : done.uncatch_total,       // +0x08 <- live+0x60
        start_tick        : done.start_tick,          // +0x10 <- live+0x10
        end_tick          : done.last_tick,           // +0x18 <- live+0x18  (이름이 바뀌는 유일한 필드)
        ep_ticks          : done.ep_ticks,            // +0x20 <- live+0x20
        in_range_ticks    : done.in_range_ticks,      // +0x28 <- live+0x28
        holder_ticks      : done.holder_ticks,        // +0x30 <- live+0x30
        team_holder_ticks : done.team_holder_ticks,   // +0x38 <- live+0x38
        minion_cover_ticks: done.minion_cover_ticks,  // +0x40 <- live+0x40
        soaked_hp         : done.soaked_hp,           // +0x48 <- live+0x48
        start_race_adv    : done.start_race_adv,      // +0x50 <- live+0x6c (i32)
        target_pos        : done.target_pos,          // +0x54 <- live+0x68 (i32)
        abort_src         : if aborted { self.v50_dive_ep_abort_src } else { 0 },  // +0x58, rs:167, self+0x1811
        start_model       : done.start_model,         // +0x59 <- live+0x72
        start_na          : done.start_na,            // +0x5a <- live+0x73
        start_ne          : done.start_ne,            // +0x5b <- live+0x74
        start_tgt_hp      : done.start_tgt_hp,        // +0x5c <- live+0x75
        end_reason        : end_reason,               // +0x5d <- 인자 그대로
        end_plan          : end_plan,                 // +0x5e <- (B) 의 분류 결과
        tower             : done.tower,               // +0x5f <- live+0x71
        start_in_range    : done.start_in_range & 1,  // +0x60 <- live+0x70
        aborted           : aborted as u8,            // +0x61 <- 인자 그대로
    });
    // push 는 인라인됨: len==cap 이면 RawVec::grow_one, 이후 ptr[len] 에 ptr::write, len += 1
}
// ret void

// ── 관측된 사실 (오독 방지용) ────────────────────────────────────────────────
// * live.gap_ticks(live+0x50, self+1472) 와 prev_holder_hp 의 페이로드(live+0x8) 는
//   take() 이후 dbg_value 에서 poison — V50DiveEpisode 에 대응 필드가 없어 그대로 버려진다.
// * end_plan 분류는 (A)(C) 어느 쪽에도 게이트되지 않아, live 가 None 이어도 매번
//   BigPlan::get_name() 으로 String 을 할당하고 최대 8회 문자열 검사를 돌린다.
// * 호출부(m13.ll:23653, 23856): 한쪽은 (aborted=false, end_reason=0) 리터럴,
//   다른 쪽은 end_reason phi 로 {1,2,3,8} ∪ {4,5,6,7} 중 하나가 들어온다.
